"""D2 (user via advisor 14, 2026-10-28): label_alpha_100_0 as a v5 SUPPLEMENT, generated by the unchanged
scripts/generate_partitions_v4.py (d872830d; repro of label_alpha x4 byte-identical, r8_draft/partition_regen_check.py).
Only the OUTPUT location changes (module global PARTITIONS_BASE_DIR -> <out>/partitions); inputs, functions, seed rule
(RandomState(42 + int(alpha * 100)) = 10042) and audit are the original. v4 (partition_spec_v4.json + partitions/) untouched.
Writes <out>/ (create-once, atomic): partitions/label_alpha_100_0/client_0{0..4}.jsonl, PARTITION_SPEC_V5_SUPPLEMENT.json
(same audit fields as v4 + provenance), PARTITION_V5_LOCK.json (sha of every file). Runs the generation twice and asserts
identical shard bytes. Usage: python -B gen_alpha100_v5.py <out_dir>    (stage2 venv: needs sklearn for the module import)
"""
import hashlib
import importlib.util
import json
import sys
from pathlib import Path

WS = Path(r"<WORKSPACE_ROOT>")
GEN = WS / "scripts/generate_partitions_v4.py"
GEN_SHA = "d872830d16689577caa2cbf54aa23265a11f35b7b42f3a0a58f7ac1dfd3a98df"
V4 = WS / "dataset/mixed/pv_pd_v3/partition_spec_v4.json"
OUT = Path(sys.argv[1])
ALPHA = 100.0
NAME = "label_alpha_100_0"


def sha(p):
    return hashlib.sha256(Path(p).read_bytes()).hexdigest()


def gen(base):
    s = importlib.util.spec_from_file_location("gpv4", GEN)
    g = importlib.util.module_from_spec(s)
    s.loader.exec_module(g)
    assert g.ROOT == WS
    g.PARTITIONS_BASE_DIR = base / "partitions"      # output only
    p = g.PartitionPipeline(seed=42, num_clients=5)
    assignment, status = p.partition_label_dirichlet(ALPHA)
    audit = p.audit_and_save_scenario(NAME, assignment, status, extra_meta={"skew_type": "label_dirichlet", "alpha_label": ALPHA})
    return g, p, audit


def main():
    assert sha(GEN) == GEN_SHA, "generator sha"
    v4_before = sha(V4)
    assert not OUT.exists(), ("create-once", OUT)
    tmp = OUT.with_name(OUT.name + ".tmp")
    chk = Path(r"<PC_PATH>/q15proto") / (OUT.name + ".check." + hashlib.sha256(str(OUT).encode()).hexdigest()[:8])   # scratch, outside the workspace
    assert not tmp.exists() and not chk.exists()
    g, p, audit = gen(tmp)
    _, _, audit2 = gen(chk)
    assert audit["status"] == "PASS", audit["status"]
    assert audit["shard_hashes"] == audit2["shard_hashes"], "generation not deterministic"
    for k in audit["shard_hashes"]:
        assert (tmp / "partitions" / NAME / k).read_bytes() == (chk / "partitions" / NAME / k).read_bytes()
    v4 = json.loads(V4.read_text(encoding="utf-8"))
    spec = {"spec_version": "5.0.0-supplement", "supplements": "partition_spec_v4.json (v4 unchanged)",
            "v4_sha256": v4_before, "release_name": v4["release_name"], "release_manifest_sha256": g.sha256_file(g.RELEASE_MANIFEST_PATH),
            "seed": 42, "num_clients": 5, "n_train_samples": p.total_samples, "num_scene_groups": p.num_groups,
            "generator": {"file": "scripts/generate_partitions_v4.py", "sha256": GEN_SHA, "function": "partition_label_dirichlet",
                          "alpha": ALPHA, "rng_seed": 42 + int(ALPHA * 100), "output_redirect_only": True,
                          "wrapper": "plans/cai-thien-train-20261015/r8_draft/gen_alpha100_v5.py", "wrapper_sha256": sha(Path(__file__))},
            "decision": "D2 user via advisor 14 2026-10-28: add alpha 100 for the alpha sweep 100 / 10 / 1 / 0.5 / 0.1",
            "scenarios": {NAME: audit}}
    assert spec["release_manifest_sha256"] == v4["release_manifest_sha256"]
    (tmp / "PARTITION_SPEC_V5_SUPPLEMENT.json").write_bytes(json.dumps(spec, indent=2, ensure_ascii=False).encode("utf-8"))
    files = {str(f.relative_to(tmp)).replace("\\", "/"): sha(f) for f in sorted(tmp.rglob("*")) if f.is_file()}
    (tmp / "PARTITION_V5_LOCK.json").write_bytes(json.dumps({"files": files}, indent=1).encode("utf-8"))
    assert sha(V4) == v4_before, "v4 changed"
    tmp.rename(OUT)
    print(json.dumps({"status": audit["status"], "n_k": [audit["client_stats"][k]["n_k"] for k in sorted(audit["client_stats"])],
                      "mean_js": audit["mean_js_divergence"], "mean_entropy": audit["mean_entropy"],
                      "supported_classes": [audit["client_stats"][k]["supported_classes"] for k in sorted(audit["client_stats"])],
                      "lock_sha256": sha(OUT / "PARTITION_V5_LOCK.json"),
                      "spec_sha256": sha(OUT / "PARTITION_SPEC_V5_SUPPLEMENT.json"), "check_dir_left": str(chk)}))


if __name__ == "__main__":
    main()
